    foreach($option_before as $name=>$before){$current=$wpdb->get_row($wpdb->prepare("SELECT option_value,autoload FROM {$wpdb->options} WHERE option_name=%s",$name),ARRAY_A);if(is_array($before)){if(is_array($current)){$r=$wpdb->update($wpdb->options,array('option_value'=>$before['option_value'],'autoload'=>$before['autoload']),array('option_name'=>$name),array('%s','%s'),array('%s'));if($r===false)$cleanup_ok=false;}else if($wpdb->insert($wpdb->options,array('option_name'=>$name,'option_value'=>$before['option_value'],'autoload'=>$before['autoload']),array('%s','%s','%s'))!==1)$cleanup_ok=false;}else if(is_array($current)&&$wpdb->delete($wpdb->options,array('option_name'=>$name),array('%s'))!==1)$cleanup_ok=false;wp_cache_delete($name,'options');}
    wp_cache_delete('alloptions','options');$after_count=(int)$wpdb->get_var("SELECT COUNT(*) FROM `{$escaped}`");if($wpdb->last_error!==''||$after_count!==$row_count_before||!$index_is($read_index(),$expected,1))$cleanup_ok=false;
